<script setup lang="ts">
import { computed } from 'vue'
import type { JsonValue, ScenarioResult } from '~/types/generation'
import { moderationLabel } from '~/utils/generation'
const props = defineProps<{ scenario: ScenarioResult }>()
defineEmits<{ inspect: [id: string] }>()
const revision = computed(() => props.scenario.revision), content = computed(() => revision.value?.content_payload ?? {})
const sections = [{ id: 'purpose', label: 'Цель и результат' }, { id: 'preparation', label: 'Подготовка' }, { id: 'stages', label: 'Ход мероприятия' }, { id: 'roles', label: 'Роли участников' }, { id: 'materials', label: 'Материалы' }, { id: 'recommendations', label: 'Рекомендации' }, { id: 'sources', label: 'Источники и факты' }]
const stages = computed(() => Array.isArray(content.value.stages) ? content.value.stages.filter(v => v && typeof v === 'object' && !Array.isArray(v)) as Record<string, JsonValue>[] : [])
function jump(id: string) { const section = document.getElementById(`scenario-${id}`); section?.scrollIntoView({ block: 'start', behavior: 'instant' }); section?.focus({ preventScroll: true }) }
function range(index: number) { const from = stages.value.slice(0, index).reduce((n, s) => n + (typeof s.duration_minutes === 'number' ? s.duration_minutes : 0), 0); const duration = stages.value[index]?.duration_minutes; return typeof duration === 'number' ? `${from}–${from + duration} мин` : 'Хронометраж не указан' }
</script>
<template><div class="scenario-result"><header><p class="muted">Мои мероприятия / Просмотр сценария</p><h1>{{ scenario.title }}</h1><div class="scenario-badges"><UiBadge>{{ ({ draft: 'Черновик', completed: 'Есть подтверждение ревизии', archived: 'Архив' } as Record<string,string>)[scenario.status] ?? scenario.status }}</UiBadge><UiBadge tone="neutral">{{ moderationLabel(scenario.moderation_status) }}</UiBadge><span v-if="revision" class="muted">Версия {{ revision.version_number }} · {{ revision.total_duration_minutes }} минут</span></div></header><slot name="actions" /><UiAlert tone="warning"><div class="generation-warning"><img src="/icons/fe006/alert.svg" width="20" height="20" alt=""><div><strong>Это рабочий проект для проверки педагогом</strong><p>Проверьте содержание, факты и доступность заданий. Завершение генерации и статус модерации не означают человеческое подтверждение.</p></div></div></UiAlert><UiAlert v-if="scenario.provider === 'mock'" tone="warning">Демонстрационный результат MockLlmProvider на backend. Внешняя LLM не использовалась.</UiAlert><p v-else-if="scenario.provider === 'litellm'" class="muted">Сгенерировано ИИ · {{ scenario.model || 'Модель не указана сервером' }}. Проверьте материал перед проведением.</p><p v-else-if="!scenario.provider" class="muted">Поставщик генерации не указан в ответе сценария.</p><UiAlert v-if="revision && !revision.is_current" tone="warning">После загрузки появилась другая текущая ревизия. Здесь показана версия {{ revision.version_number }}; перечитайте сценарий для актуальных данных.</UiAlert><ScenarioQualityNotice v-if="revision" :review="revision.quality_review ?? scenario.quality_review" /><UiState v-if="!revision" kind="empty" title="Ревизия сценария отсутствует" /><div v-else class="scenario-layout"><nav class="scenario-toc" aria-label="Оглавление сценария"><strong>ОГЛАВЛЕНИЕ</strong><a v-for="(section, i) in sections" :key="section.id" :href="`#scenario-${section.id}`" @click.prevent="jump(section.id)">0{{ i + 1 }} · {{ section.label }}</a></nav><div class="scenario-sections"><section id="scenario-purpose" tabindex="-1"><h2>01 / Цель и ожидаемый результат</h2><slot name="purpose"><p>{{ revision.concept }}</p><h3>Педагогическая цель</h3><p>{{ revision.pedagogical_goal }}</p><h3>Воспитательные задачи</h3><ScenarioJson :value="content.pedagogical_tasks" /></slot><h3>Ожидаемые результаты</h3><ScenarioJson :value="content.expected_outcomes" /><h3 v-if="content.pedagogical_mechanism">Педагогический механизм</h3><ScenarioJson v-if="content.pedagogical_mechanism" :value="content.pedagogical_mechanism" /></section><section id="scenario-preparation" tabindex="-1"><h2>02 / Подготовка педагога</h2><ScenarioJson :value="content.preparation_checklist" /><h3>Целевая аудитория</h3><ScenarioJson :value="content.target_audience" /></section><section id="scenario-stages" tabindex="-1"><h2>03 / Ход мероприятия</h2><UiBadge tone="success">{{ revision.total_duration_minutes }} минут всего</UiBadge><slot name="stages"><p v-if="!stages.length">Этапы не включены в ответ.</p><article v-for="(stage, i) in stages" :key="i" class="scenario-stage"><div class="section-heading"><strong>{{ range(i) }}</strong><span>{{ stage.duration_minutes }} минут</span></div><h3>{{ stage.title }}</h3><h4>Действия педагога</h4><p>{{ stage.teacher_actions }}</p><h4>Действия участников</h4><p>{{ stage.student_actions }}</p><template v-if="stage.dialogue_prompts"><h4>Вопросы для обсуждения</h4><ScenarioJson :value="stage.dialogue_prompts" /></template><UiAlert v-if="stage.teacher_tips">{{ stage.teacher_tips }}</UiAlert><p v-if="stage.transition_text" class="muted">{{ stage.transition_text }}</p></article></slot><h3 v-if="content.activities">Задания и обратная связь</h3><ScenarioJson v-if="content.activities" :value="content.activities" /></section><section id="scenario-roles" tabindex="-1"><h2>04 / Роли и участие каждого</h2><ScenarioJson :value="content.roles" /></section><section id="scenario-materials" tabindex="-1"><h2>05 / Материалы и задания</h2><slot name="materials"><ScenarioJson :value="content.materials" /></slot><h3>Ресурсы и реквизит</h3><ScenarioJson :value="content.props" /><p class="muted">Материалы включаются в серверные документы. Формат и доступность скачивания проверьте в экспорте.</p></section><section id="scenario-recommendations" tabindex="-1"><h2>06 / Методические рекомендации</h2><ScenarioJson :value="content.teacher_instructions" /></section><section id="scenario-sources" tabindex="-1"><h2>07 / Культурные сведения, источники и доказательства</h2><ScenarioCulturalClaims :value="content.cultural_claims" @inspect="$emit('inspect', $event)" /></section></div><aside class="scenario-side"><slot name="moderation"><UiCard><h3>Проверка материала</h3><p>{{ moderationLabel(revision.moderation_status) }}</p><p v-if="revision.moderation_state?.p0_violations_count != null">Критические замечания: {{ revision.moderation_state.p0_violations_count }}</p><p v-if="revision.moderation_state?.p1_violations_count != null">Прочие замечания: {{ revision.moderation_state.p1_violations_count }}</p><p v-if="revision.moderation_state?.moderator_notes">{{ revision.moderation_state.moderator_notes }}</p><p>Общий статус проверки не удостоверяет каждое культурное утверждение.</p></UiCard></slot><UiAlert><div class="generation-warning"><img src="/icons/fe006/info.svg" width="20" height="20" alt=""><div><strong>Личные данные не нужны</strong><p>Не добавляйте ФИО детей, сведения о здоровье и семейных обстоятельствах.</p></div></div></UiAlert><p class="muted">Режим чтения. Редактирование и подтверждение доступны в редакторе при наличии школьных полномочий. Экспорт и история доступны через отдельное действие; допуск проверяется сервером.</p></aside></div></div></template>
